import { describe, expect, test } from "bun:test";
import { decodeEventLog, type Hex } from "viem";
import { LAUNCHPAD_SOURCES } from "./config";
import {
  scanBlockRange,
  toLaunch,
  type DecodedLaunchLog,
} from "./factory-log-indexer.service";

describe("scanBlockRange", () => {
  test("retries oversized ranges by reducing the block window", async () => {
    const requested: Array<[bigint, bigint]> = [];
    const result = await scanBlockRange(10n, 17n, 4n, async (from, to) => {
      requested.push([from, to]);
      if (to - from + 1n > 2n) throw new Error("requested range too large");
      return [`${from}-${to}`];
    });

    expect(result).toEqual(["10-11", "12-13", "14-15", "16-17"]);
    expect(requested).toEqual([
      [10n, 13n],
      [10n, 11n],
      [12n, 13n],
      [14n, 15n],
      [16n, 17n],
    ]);
  });

  test("surfaces non-range RPC errors", async () => {
    await expect(
      scanBlockRange(1n, 2n, 2n, async () => {
        throw new Error("unauthorized");
      }),
    ).rejects.toThrow("unauthorized");
  });
});

// Real mainnet logs captured 2026-10-06 from rpc.mainnet.arc.io.
const ARGUS_LOG = {
  topics: [
    "0x1d8917231579f8ce39407f0d616f36f357b07329b0ce5164d0754ac15145ce0a",
    "0x00000000000000000000000038b25f586f7324feee84dd96f48fb81e76708ba4",
    "0x00000000000000000000000018cd25ddc930e5b61ec52e93f3a82d53694a2f2a",
  ] as [Hex, ...Hex[]],
  data: "" as Hex,
  blockNumber: 0x176af50n,
  transactionHash:
    "0x6694a4c1836189b97854c77801160e39e96ffed5a3d97e2ed72cfaafeec48af8" as Hex,
  logIndex: 0x1e,
};

const TOLLY_LOG = {
  topics: [
    "0x875522b092d9e19a1de359e4bd218090d582fa521c9733889acf1a5ff1941255",
    "0x000000000000000000000000b2c834177d77fe0c22152d25162e956c89e0ff31",
    "0x0000000000000000000000004fc88b308723e5ff08003d696aed714768b359fa",
  ] as [Hex, ...Hex[]],
  data: "" as Hex,
  blockNumber: 0x1767ca4n,
  transactionHash:
    "0x6cfbd0925cb8559800c60cf8367ebbd95087737a9d76b1bd6f9b6e831e3baf51" as Hex,
  logIndex: 0x42,
};

function decode(sourceId: "argus" | "tolly", raw: typeof ARGUS_LOG) {
  const source = LAUNCHPAD_SOURCES.find((s) => s.id === sourceId)!;
  const { args } = decodeEventLog({
    abi: [source.event],
    topics: raw.topics,
    data: raw.data,
  });
  return toLaunch({ ...raw, args } as unknown as DecodedLaunchLog);
}

describe("toLaunch", () => {
  test("decodes a real Argus launch with its Uniswap v4 poolId", () => {
    expect(decode("argus", ARGUS_LOG)).toEqual({
      token: "0x38b25f586f7324feee84dd96f48fb81e76708ba4",
      creator: "0x18cd25ddc930e5b61ec52e93f3a82d53694a2f2a",
      name: "Tolly",
      symbol: "TOIIY",
      poolRef:
        "0xa4b9a831565b986be30ccdf25cf9b3feae2293aa07834963beadc915bfd0ee9b",
      uri: "ipfs://bafkreiaa2a2clojuifhiimxu3knnkokmbrjn74co63nm5viwxad7xbkuda",
      links: ["https://x.com/TollyLabs"],
      blockNumber: 0x176af50n,
      transactionHash: ARGUS_LOG.transactionHash,
      logIndex: 0x1e,
    });
  });

  test("decodes a real Tolly launch with its bonding-curve contract", () => {
    const launch = decode("tolly", TOLLY_LOG);
    expect(launch?.token).toBe("0xb2c834177d77fe0c22152d25162e956c89e0ff31");
    expect(launch?.symbol).toBe("ARCHANGEL");
    expect(launch?.poolRef).toBe("0x45185dfcc73f36ce962e3df262c5466e51c7096a");
    expect(launch?.uri).toBe("https://i.redd.it/l6xppuh8hu7a1.png");
  });

  test("skips logs missing a token address", () => {
    expect(
      toLaunch({
        args: { creator: "0x0000000000000000000000000000000000000001" },
        blockNumber: 1n,
        transactionHash: "0x01",
        logIndex: 0,
        topics: [],
        data: "0x",
      }),
    ).toBeNull();
  });
});
